#include <Arduino.h>
#include <math.h>

#define DHT_PIN 12

// Seven-segment digits
// Bit 0 = a, bit 1 = b, ... bit 6 = g
const byte cyfry[10] = {
  63, 6, 91, 79, 102,
  109, 125, 7, 127, 111
};

int minimum, maksimum;
int jasnosc = 0;
int wilgotnosc = 0;
int temperatura = 0;

byte tryb = 0;  // 0 = light, 1 = humidity, 2 = temperature

unsigned long ostatnieSwiatlo = 0;
unsigned long ostatniDHT = 0;
unsigned long czasZmiany = 0;
unsigned long czasEtykiety = 0;

bool poprzedniOdczyt = HIGH;
bool stanPrzycisku = HIGH;
bool pokazEtykiete = false;

// --------------------------------------------------
// DHT11 SENSOR - BUILT IN, NO EXTERNAL LIBRARY
// --------------------------------------------------

bool odczytajDHT11(int &humidity, int &temperature) {

  byte dane[5] = {0, 0, 0, 0, 0};

  // Start signal
  pinMode(DHT_PIN, OUTPUT);
  digitalWrite(DHT_PIN, LOW);
  delay(20);

  digitalWrite(DHT_PIN, HIGH);
  delayMicroseconds(30);

  pinMode(DHT_PIN, INPUT_PULLUP);

  // Sensor response
  if (pulseIn(DHT_PIN, LOW, 120) == 0)
    return false;

  if (pulseIn(DHT_PIN, HIGH, 120) == 0)
    return false;

  // Read 40 bits
  for (int i = 0; i < 40; i++) {

    if (pulseIn(DHT_PIN, LOW, 100) == 0)
      return false;

    unsigned long czas = pulseIn(DHT_PIN, HIGH, 120);

    if (czas == 0)
      return false;

    dane[i / 8] <<= 1;

    if (czas > 40)
      dane[i / 8] |= 1;
  }

  // Checksum
  byte suma = dane[0] + dane[1] + dane[2] + dane[3];

  if (suma != dane[4])
    return false;

  // DHT11 values
  humidity = dane[0];
  temperature = dane[2];

  return true;
}

// --------------------------------------------------
// DISPLAY SEGMENTS
// --------------------------------------------------

void segmenty(byte wzor) {

  for (int i = 0; i < 7; i++) {
    digitalWrite(
      i + 2,
      bitRead(wzor, i) ? LOW : HIGH
    );
  }
}

void cyfra(int n) {

  if (n < 0 || n > 9)
    n = 0;

  segmenty(cyfry[n]);
}

// --------------------------------------------------
// DISPLAY NUMBER
// --------------------------------------------------

void wyswietl(int liczba) {

  liczba = constrain(liczba, 0, 99);

  // Units
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  cyfra(liczba % 10);

  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  // Tens
  cyfra(liczba / 10);

  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);
}

// --------------------------------------------------
// DISPLAY MODE LETTER
// --------------------------------------------------

void wyswietlLitere() {

  byte wzor;

  if (tryb == 0)
    wzor = 0b00111000;  // L

  else if (tryb == 1)
    wzor = 0b01110110;  // H

  else
    wzor = 0b01111000;  // t

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  segmenty(wzor);

  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);

  delay(2);
}

// --------------------------------------------------
// READ SENSORS
// --------------------------------------------------

void pomiary() {

  unsigned long teraz = millis();

  // Light sensor
  if (teraz - ostatnieSwiatlo >= 400) {

    ostatnieSwiatlo = teraz;

    int wartosc = analogRead(A0);

    if (wartosc < minimum)
      minimum = wartosc;

    if (wartosc > maksimum)
      maksimum = wartosc;

    if (maksimum > minimum) {

      jasnosc = 99L * (wartosc - minimum)
                / (maksimum - minimum);
    }

    jasnosc = constrain(jasnosc, 0, 99);
  }

  // DHT11 - read every 2 seconds
  if (teraz - ostatniDHT >= 2000) {

    ostatniDHT = teraz;

    int h, t;

    if (odczytajDHT11(h, t)) {

      wilgotnosc = constrain(h, 0, 99);
      temperatura = constrain(t, 0, 99);
    }
  }
}

// --------------------------------------------------
// BUTTON
// --------------------------------------------------

void przycisk() {

  bool odczyt = digitalRead(9);

  if (odczyt != poprzedniOdczyt)
    czasZmiany = millis();

  if (millis() - czasZmiany >= 40 &&
      odczyt != stanPrzycisku) {

    stanPrzycisku = odczyt;

    if (stanPrzycisku == LOW) {

      tryb = (tryb + 1) % 3;

      czasEtykiety = millis();
      pokazEtykiete = true;
    }
  }

  poprzedniOdczyt = odczyt;
}

// --------------------------------------------------
// SETUP
// --------------------------------------------------

void setup() {

  for (int i = 2; i <= 8; i++)
    pinMode(i, OUTPUT);

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  pinMode(9, INPUT_PULLUP);

  pinMode(DHT_PIN, INPUT_PULLUP);

  minimum = analogRead(A0);
  maksimum = minimum;
}

// --------------------------------------------------
// MAIN LOOP
// --------------------------------------------------

void loop() {

  pomiary();
  przycisk();

  if (pokazEtykiete &&
      millis() - czasEtykiety < 1000) {

    wyswietlLitere();

  } else {

    pokazEtykiete = false;

    int liczba;

    if (tryb == 0)
      liczba = jasnosc;

    else if (tryb == 1)
      liczba = wilgotnosc;

    else
      liczba = temperatura;

    wyswietl(liczba);
  }
}

